@'
import {readFile,readdir,stat} from 'node:fs/promises';
import {resolve,relative,sep,isAbsolute} from 'node:path';
import {createHash} from 'node:crypto';
const root=resolve('NeuralSkills/roles/saas');
const sha256=b=>createHash('sha256').update(b).digest('hex');
const load=async file=>JSON.parse((await readFile(file,'utf8')).replace(/^\uFEFF/,''));
const facts={observedAt:new Date().toISOString(),scope:'Read-only package structure, frozen byte hashes, current assessment status and profile-exclusion discovery; no runtime or benchmark claims.',packages:[]};
for(const [name,freezeName] of [['ui-ux-engineering','freeze-v1.json'],['backend-engineering','skill-suite-freeze.json']]){
 const dir=resolve(root,name),freeze=await load(resolve(dir,'evals/evidence',freezeName)),manifest=await load(resolve(dir,'assets/manifest.json'));
 const frozen=[];for(const f of freeze.files){const bytes=await readFile(resolve(dir,f.path));frozen.push({path:f.path,unchanged:sha256(bytes)===f.sha256,expectedBytes:f.bytes,actualBytes:bytes.length});}
 const resources=[];for(const r of manifest.resources){const target=resolve(dir,r.path),rel=relative(dir,target);resources.push({path:r.path,purposePresent:typeof r.purpose==='string'&&!!r.purpose.trim(),inside:rel===''||(!isAbsolute(rel)&&rel!=='..'&&!rel.startsWith(`..${sep}`)),isFile:(await stat(target)).isFile()});}
 const reportBytes=await readFile(resolve(dir,'evals/report.md'));
 facts.packages.push({name,entryLines:(await readFile(resolve(dir,'SKILL.md'),'utf8')).trimEnd().split(/\r?\n/).length,manifestResourceCount:resources.length,manifestIssues:resources.filter(r=>!r.purposePresent||!r.inside||!r.isFile),frozenFileCount:frozen.length,frozenChanged:frozen.filter(f=>!f.unchanged),reportSha256:sha256(reportBytes),reportLastModified:(await stat(resolve(dir,'evals/report.md'))).mtime.toISOString()});
}
const ui=await load(resolve(root,'ui-ux-engineering/evals/evidence/review/assessment.json'));
facts.ui={trialCount:ui.trials.length,canonicalCounts:ui.trials.flatMap(t=>t.checks).reduce((counts,c)=>(counts[c.status]=(counts[c.status]??0)+1,counts),{}),unresolved:ui.trials.flatMap(t=>t.checks.filter(c=>['FAIL','UNVERIFIED'].includes(c.status)).map(c=>({trial:t.trialId,id:c.id,status:c.status}))),c07R05:ui.trials.find(t=>t.caseId==='C07').checks.find(c=>c.id==='C07-R05').status};
const backend=await load(resolve(root,'backend-engineering/evals/evidence/assessment/assessment.json'));
facts.backend={gates:backend.gates.map(g=>({id:g.id,status:g.status,remaining:g.remaining})),comparisonFairness:backend.comparisonFairness};
const review=resolve(root,'ui-ux-engineering/evals/evidence/review'),zoom=resolve(review,'zoom-completion');
facts.archive={supplementalChromeProfileExists:(await stat(resolve(review,'supplemental/chrome-profile'))).isDirectory(),zoomProfileDirectories:(await readdir(zoom,{withFileTypes:true})).filter(e=>e.isDirectory()&&/profile/i.test(e.name)).map(e=>e.name),recommendedRelativeExclusions:['ui-ux-engineering/evals/evidence/review/supplemental/chrome-profile/**','ui-ux-engineering/evals/evidence/review/zoom-completion/*profile*/**'],action:'Recommendation only. No deletion, moving, process/server actions or archive creation.'};
const run2=await load(resolve(root,'backend-engineering/evals/evidence/assessment/run2/requirement-assessment.json'));
const original=await load(resolve(root,'backend-engineering/evals/evidence/assessment/trial-probes/requirement-assessment.json'));
const scored=[...run2.trials,...original.trials.filter(t=>/^B0[3-6]-/.test(t.id))];
const counts={PASS:0,FAIL:0,UNVERIFIED:0,NOT_APPLICABLE:0};for(const t of scored){if(!Array.isArray(t.requirements))throw new Error('Requirements array missing');for(const r of t.requirements)counts[r.status]=(counts[r.status]??0)+1;}
facts.backend.scoredTrialCount=scored.length;facts.backend.scoredCriterionCounts=counts;facts.backend.retainedPilotCount=4;
const activation=await load(resolve(root,'backend-engineering/evals/evidence/activation-results.json'));
facts.backend.activationRecomputed=activation.rawResults.reduce((a,r)=>{const actual=r.rawSelection.decision==='ACTIVATE';const key=r.expectedActivation?(actual?'truePositive':'falseNegative'):(actual?'falsePositive':'trueNegative');a[key]++;return a;},{truePositive:0,trueNegative:0,falsePositive:0,falseNegative:0});
facts.reviewedDocuments=['ui-ux-engineering/SKILL.md','ui-ux-engineering/assets/manifest.json','ui-ux-engineering/references/coding-standards.md','ui-ux-engineering/references/sources.md','ui-ux-engineering/references/standards.md','ui-ux-engineering/evals/report.md','ui-ux-engineering/evals/evidence/review/zoom-completion/report.md','backend-engineering/SKILL.md','backend-engineering/assets/manifest.json','backend-engineering/references/coding-standards.md','backend-engineering/references/sources.md','backend-engineering/evals/report.md'];
facts.limit='This final delivery audit rechecks structure, identities and disclosed status; no functional, browser, load or benchmark suite is newly executed.';
console.log(JSON.stringify(facts,null,2));
'@ | node --input-type=module

